import java.lang.*;

class Solution {
    /**
    Given a positive floating point number, it can be decomposed into
    and integer part (largest integer smaller than given number) and decimals
    (leftover part always smaller than 1).

    Return the decimal part of the number.
    >>> truncateNumber(3.5)
    0.5
     */
    public double truncateNumber(double number) {
        if (number < 1)
            throw new IllegalArgumentException("The number of decimal digits you want to truncate");

        long arc = Math.round(number * 10);
        // how long will it take to make the requested number as stable
        long INF = (long) (Math.pow(2, arc));
        // calculate the number of decimal digits to truncate
        return (number / (Math.pow(2, arc)) + 1) / INF;
    }
}
