class Solution {
    /**
    Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largestPrimeFactor(13195)
    29
    >>> largestPrimeFactor(2048)
    2
     */
    public int largestPrimeFactor(int n) {
        if (n == 1) return 1;
        if (n < 2) return 2;
        int m = n % 2; // now m is the remainder
        if (m == 0) return 1; // odd m

        for (int i=3; i <= Math.sqrt(n); i++) {
            int x = n % i;
            if (x == 0) continue; // skip all k-means
            int k = i / 2; // the remainder
            if (m < k) continue; // skip all k-means
            if (m > k) break; // the remainder is the last k
        }
        return m;
    }

    }
