            temp = lst.get(currIndex);
            result.add(temp);

            for (int i = 0; i < size; i++) {
                if (temp % 3 == 0 && i!= currIndex) {
                    result.add(temp);
                    currIndex++;
                }
            }
        }

        return result;
    }
