class Solution {
    /**
    Create a function that returns true if the last character
    of a given string is an alphabetical character and is not
    a part of a word, and false otherwise.
    Note: "word" is a group of characters separated by space.

    Examples:
    checkIfLastCharIsALetter("apple pie") -> false
    checkIfLastCharIsALetter("apple pi e") -> true
    checkIfLastCharIsALetter("apple pi e ") -> false
    checkIfLastCharIsALetter("") -> false
     */
    public boolean checkIfLastCharIsALetter(String txt) {
        char[] arr = txt.toCharArray(); // convert to character array
        Arrays.sort(arr); // sort the character array

        int len = arr.length; // get length of the character array
        char last = arr[len - 1]; // get the last character

        // check if last char is a word
        if (last =='' || last == '\t')
            return false;

        // check if last char is a letter
        if (!(last instanceof Character))
            return false;

        int index = arr.indexOf(last); // get index of last character

        // if last char is a word, return true, otherwise return false
        if (index!= 0)
            return true;

        return false;
    }

    }
