    Example
    isEqualToSumEven(4) == false
    isEqualToSumEven(6) == false
    isEqualToSumEven(8) == true
     */
    public boolean isEqualToSumEven(int n) {
        if (n < 4) return false;
        int sum = 0;
        for (int i = 0; i < n; i++)
            sum += i;
        return (sum == n);
    }

    /**
    In this approach, we first take the sum of the given number, and then we add 1 to that sum
    for every number in the given array.
    Example
    for (int i = 0; i < 5; i++)
        sum += i
    for (int i = 0; i < 10; i++)
        sum += i
        sum += 1
    for (int i = 0; i < 20; i++)
        sum += i

