class Solution {
    /**
    A simple program which should return the value of x if n is
    a prime number and should return the value of y otherwise.

    Examples:
    for xOrY(7, 34, 12) == 34
    for xOrY(15, 8, 5) == 5
     */
    public int xOrY(int n, int x, int y) {
        if (n % 2 == 1) {
            return x;
        }

        int m = n / 2;
        int a = x;

        while (m > 0) {
            if (a % 2 == 1) {
